def productWindow(nums: list[int], k: int) -> int:
    if not nums or k <= 0 or k > len(nums):
        return 0
    max_prod = float('-inf')
    for i in range(len(nums) - k + 1):
        curr_prod = 1
        for j in range(i, i + k):
            curr_prod *= nums[j]
        if curr_prod > max_prod:
            max_prod = curr_prod
    return max_prod

